namespace CleanArchitecture.Blazor.Application.Features.Systems.EventHandlers;

public class SystemUpdatedEventHandler : INotificationHandler<SystemUpdatedEvent>
{
    private readonly ILogger<SystemUpdatedEventHandler> _logger;

    public SystemUpdatedEventHandler(
        ILogger<SystemUpdatedEventHandler> logger
    )
    {
        _logger = logger;
    }

    public Task Handle(SystemUpdatedEvent notification, CancellationToken cancellationToken)
    {
        _logger.LogInformation("System updated: {SystemName} (ID: {SystemId}) by {ModifiedBy} at {ModifiedOn}", 
            notification.Item.Name, 
            notification.Item.Id, 
            notification.Item.LastModifiedBy, 
            notification.Item.LastModified);
        
        return Task.CompletedTask;
    }
}